// each connection's progress while a job runs: waiting, syncing, done or failed (the server reports it; the last result stays until the next job)
let LASTITEMS={};
function syncRow(s){const it=(JOB&&JOB.items||{})[s.k]||(!JOB&&LASTITEMS[s.k])||null,st=it&&it.state;
let dot=`<i class="live ${s.state}"></i>`,msg=esc(s.text)+(s.msg?" · "+esc(s.msg):"");
if(st=="waiting"){dot='<i class="live warn"></i>';msg="Waiting for its turn…"}
else if(st=="syncing"){dot='<i class="live spin"></i>';msg=(JOB&&JOB.kind=="test"?"Testing":"Syncing")+"…"}
else if(st=="done"){dot='<i class="live ok"></i>';msg="Done"+(it.added!=null?" · "+(it.added?it.added+" new transaction"+(it.added==1?"":"s"):"nothing new"):"")}
else if(st=="failed"){dot='<i class="live bad"></i>';msg="Failed"+(it.msg?" · "+esc(friendlyErr(it.msg)||it.msg):"")}
else if(st=="skipped"){msg=esc(s.text)+" · not connected"}
return `<div class="row"><i class="live ${s.state}"></i><div class="grow"><b>${esc(s.n)}</b><div class="sm">${msg}</div></div>${s.goConn&&!JOB?`<button class="btn o s" data-a="goConn">${s.state=="bad"?"Fix":"Connect"}</button>`:""}</div>`.replace('<i class="live '+s.state+'"></i>',dot)}
function syncRowsRefresh(){const e=$("syncRows");if(e)e.innerHTML=SRC.map(syncRow).join("")}
function openSync(){LASTITEMS={};openSheet(`<h3>Sources</h3><div id="syncRows">`+SRC.map(syncRow).join("")+`</div>`+`<div class="sm" style="margin-top:10px"><i class="live ok"></i> connected and synced &nbsp; <i class="live warn"></i> not connected or waiting &nbsp; <i class="live bad"></i> failed or locked</div><div class="sm" style="margin-top:6px">Read-only: the app never changes anything at your banks.</div><div class="flex" style="justify-content:flex-end;gap:8px;margin-top:10px"><button class="btn o" data-a="syncNow">Sync now</button><button class="btn" data-a="close">Done</button></div>`)}
