function nav(v,noPush){closeSheet();document.querySelectorAll(".view").forEach(x=>x.classList.toggle("on",x.id==v));document.querySelectorAll(".nb[data-v]").forEach(b=>b.classList.toggle("on",b.dataset.v==v));renderHead(v);scrollTo(0,0);if(!noPush&&v!=curView){const st={v};if(history.state&&history.state.o)history.replaceState(st,"","#"+v);else history.pushState(st,"","#"+v)}else if(history.state&&history.state.o)history.replaceState({v},"","#"+v);curView=v;navPill(true);renderView(v);if(HELPOPEN)helpRender();if(v=="set"){if(setTab=="conn"||setTab=="sync")loadConn();if(setTab=="sync")loadSyncLog();if(setTab=="sec")renderSec();if(setTab=="prof")renderProfile();if(setTab=="backup")loadBackup();if(setTab=="alr"||setTab=="notify")loadNch()}}
async function notify(title,body){if(window.HE&&HE.on){title=HE.T(String(title));body=HE.T(String(body))}if(!("Notification" in window)||Notification.permission!="granted")return false;try{const reg=navigator.serviceWorker&&await navigator.serviceWorker.getRegistration();if(reg&&reg.active){reg.active.postMessage({type:"notify",title,body});return true}new Notification(title,{body});return true}catch(e){return false}}
const allTags=()=>{const m={};S.tx.forEach(t=>{if(t.virtual)return;(t.tags||[]).forEach(g=>m[g]=(m[g]||0)+1)});(S.tagRules||[]).forEach(r=>ruleTags(r).forEach(g=>{if(!(g in m))m[g]=0}));return Object.entries(m).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))};
const ruleTags=r=>String(r&&r.t||"").split(",").map(x=>x.trim().replace(/^#+/,"")).filter(Boolean);
const normTag=v=>{v=String(v).trim().replace(/^#+/,"");if(!v)return"";const e=allTags().find(([t])=>t.toLowerCase()==v.toLowerCase());return e?e[0]:v};
function tagFill(){const e=$("fTag");if(!e)return;const v=e.value,L=allTags().filter(x=>x[1]>0);e.innerHTML='<option value="">All tags</option>'+L.map(([t,n])=>`<option value="${esc(t)}">${esc(t)} (${n})</option>`).join("");e.value=L.some(x=>x[0]==v)?v:""}
function fillFilters(){const s=$("fSrc"),c=$("fCat"),sv=s.value,cv=c.value;s.innerHTML='<option value="">All sources</option>'+[...new Set([...S.accounts.filter(a=>a.kind!="pension").map(a=>a.n)])].map(x=>`<option>${esc(x)}</option>`).join("");tagFill();c.innerHTML='<option value="">All categories</option>'+[...new Set([...catNames(),"Uncategorized"])].sort((x,y)=>x.localeCompare(y,undefined,{sensitivity:"base"})).map(x=>`<option>${esc(x)}</option>`).join("");s.value=sv;c.value=cv}
