/* ---------- one connection job at a time: test or sync ---------- */
let JOB=null,jobTick=null,jobPoll=null;
const JK={test:["Testing","Test"],sync:["Syncing","Sync"],assist:["Verifying","Verify"]},SRCN={hapoalim:"Bank Hapoalim",max:"Max",isracard:"Isracard",wise:"Wise",all:"all sources"};
const srcName=x=>SRCN[x]||x,mmss=t=>{t=Math.max(0,Math.round(t/1000));return Math.floor(t/60)+":"+String(t%60).padStart(2,"0")};
function applyJobUI(){const bar=$("jobBar");if(!bar)return;bar.style.display=JOB?"flex":"none";
if(JOB)$("jobTxt").textContent=JK[JOB.kind][0]+" "+srcName(JOB.source)+"… "+(()=>{const v=Object.values(JOB.items||{}).filter(x=>x.state!="skipped"),d=v.filter(x=>x.state=="done"||x.state=="failed").length;return JOB.source=="all"&&v.length>1?d+" of "+v.length+" · ":""})()+mmss(Date.now()-JOB.since)+(JOB.kind=="assist"?" · finish in the verification window":" · "+(JOB.source!="all"&&JOB.kind=="sync"?"usually a few minutes; a long history can take much longer. It keeps going while the bank is answering, please wait":"this can take a few minutes, please wait"));
$("syncb")&&$("syncb").classList.toggle("spinning",!!JOB);
document.querySelectorAll('[data-a="connTest"],[data-a="connSync"],[data-a="connHist"],[data-a="syncNow"],[data-a="connAssist"]').forEach(b=>{if(b.dataset.l==null){b.dataset.l=b.textContent;b.dataset.h=b.innerHTML}
const kind=b.dataset.a=="connTest"?"test":b.dataset.a=="connAssist"?"assist":"sync",mine=JOB&&JOB.kind==kind&&(b.dataset.a=="syncNow"?JOB.source=="all":(JOB.source==b.dataset.s||JOB.source=="all"));
b.disabled=!!JOB;b.classList.toggle("running",!!mine);b.title=JOB&&!mine?"Wait for the current one to finish":"";
if(mine)b.innerHTML='<i class="spinner"></i>'+JK[kind][0]+"…";else if(b.dataset.l!=null&&b.querySelector(".spinner"))b.innerHTML=b.dataset.h});
syncRowsRefresh();
document.querySelectorAll("[data-badge]").forEach(b=>{if(b.dataset.orig==null)b.dataset.orig=b.textContent;const x=b.dataset.badge,me=JOB&&(JOB.source==x||JOB.source=="all");
b.className="bd "+(me?"fl":b.dataset.bcls);if(me)b.innerHTML='<i class="spinner"></i>'+JK[JOB.kind][0]+"…";else b.textContent=b.dataset.orig});
document.querySelectorAll(".jobnote").forEach(n=>{const x=n.dataset.src,me=JOB&&(JOB.source==x||JOB.source=="all");n.classList.toggle("act",!!me);
n.textContent=!JOB?"":me?JK[JOB.kind][0]+" "+srcName(x)+"… "+mmss(Date.now()-JOB.since)+". Please wait, do not close this page.":srcName(JOB.source)+" is busy ("+JK[JOB.kind][0].toLowerCase()+"). Wait for it to finish before starting another."})}
let jobItemsT=null;
async function jobItems(){try{const j=await (await fetch("/api/jobs",{cache:"no-store"})).json();if(j&&JOB&&j.items){JOB.items=j.items;applyJobUI();syncRowsRefresh()}}catch(e){}}
function startJob(source,kind,since){JOB={source,kind,since:since||Date.now(),items:{}};clearInterval(jobTick);jobTick=setInterval(applyJobUI,1000);clearInterval(jobItemsT);jobItemsT=setInterval(jobItems,1500);applyJobUI()}
function endJob(){if(JOB&&JOB.items&&Object.keys(JOB.items).length)LASTITEMS=JOB.items;JOB=null;clearInterval(jobTick);clearInterval(jobItemsT);applyJobUI();syncRowsRefresh()}
async function runJob(source,kind,fn){if(JOB){toast("Wait for the current one to finish");return null}startJob(source,kind);try{return await fn()}finally{endJob()}}
// a job started elsewhere (another tab, the schedule, before a reload): show it and wait for it to end
async function watchJobs(){try{const j=await (await fetch("/api/jobs",{cache:"no-store"})).json();
if(j&&j.kind=="assist"&&!AS){startJob(j.source,"assist",j.since);await loadConn();assistOpen(j.source,true);return}
if(j&&!JOB){startJob(j.source,j.kind,j.since);clearInterval(jobPoll);jobPoll=setInterval(async()=>{try{const x=await (await fetch("/api/jobs",{cache:"no-store"})).json();if(!x){clearInterval(jobPoll);endJob();await load();renderAll();if(setTab=="conn")loadConn()}}catch(e){}},2500)}}catch(e){}}
{const o=openSheet;openSheet=h=>{o(h);applyJobUI()}}
